import{_ as d,C as h,o as i,c as E,a7 as t,b as l,w as a,a as n,E as r,a8 as o}from"./chunks/framework.DmcojIVA.js";const m=JSON.parse('{"title":"可观测性：分布式日志系统","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/distributed-system/observability-log.md","filePath":"development/common/distributed-system/observability-log.md","lastUpdated":1785428463000}'),c={name:"development/common/distributed-system/observability-log.md"};function p(k,e,u,g,A,B){const s=h("Mermaid");return i(),E("div",null,[e[3]||(e[3]=t(`<h1 id="ke-guan-ce-xingfen-bu-shi-ri-zhi-xi-tong" tabindex="-1">可观测性：分布式日志系统 <a class="header-anchor" href="#ke-guan-ce-xingfen-bu-shi-ri-zhi-xi-tong" aria-label="Permalink to &quot;可观测性：分布式日志系统&quot;">​</a></h1><p>日志是带时间和上下文的离散事件记录。分布式日志系统负责把不同主机、容器和服务产生的日志统一采集、处理、存储和查询，使开发者能够从分散的局部记录中还原故障现场。</p><p>日志的目标不是“记录得越多越好”，而是在可接受的成本和安全边界内，为排障、审计和业务分析保留足够证据。</p><h2 id="fen-bu-shi-ri-zhi-wei-shi-me-geng-nan" tabindex="-1">分布式日志为什么更难 <a class="header-anchor" href="#fen-bu-shi-ri-zhi-wei-shi-me-geng-nan" aria-label="Permalink to &quot;分布式日志为什么更难&quot;">​</a></h2><ul><li><strong>来源分散</strong>：同一个请求会跨越多个进程、主机、集群和区域。</li><li><strong>时钟不完全一致</strong>：机器时间偏差会让日志展示顺序与因果顺序不同。</li><li><strong>请求需要关联</strong>：必须用 <code>trace_id</code>、业务 ID 等字段关联上下文。</li><li><strong>吞吐具有突发性</strong>：故障时通常正是日志量最大、管道压力最高的时候。</li><li><strong>消息可能重复或丢失</strong>：Agent 重试、容器退出和存储限流都会影响投递。</li><li><strong>数据具有敏感性</strong>：日志可能无意记录 Token、密码、个人信息和内部拓扑。</li></ul><p>因此，日志时间戳用于缩小范围，Trace 上下文用于表达请求关联；不能只依赖肉眼按时间拼接调用链。</p><h2 id="yi-tiao-ri-zhi-ying-gai-bao-han-shi-me" tabindex="-1">一条日志应该包含什么 <a class="header-anchor" href="#yi-tiao-ri-zhi-ying-gai-bao-han-shi-me" aria-label="Permalink to &quot;一条日志应该包含什么&quot;">​</a></h2><p>优先输出结构化 JSON，而不是把所有内容拼成一句文本。字段可按下面四类组织：</p><table tabindex="0"><thead><tr><th>类型</th><th>推荐字段</th><th>说明</th></tr></thead><tbody><tr><td>时间与级别</td><td><code>timestamp</code>、<code>severity_text</code></td><td>使用带时区的 ISO 8601 时间</td></tr><tr><td>资源身份</td><td><code>service.name</code>、<code>service.version</code>、<code>deployment.environment.name</code>、<code>cloud.region</code></td><td>描述是谁产生了日志</td></tr><tr><td>执行上下文</td><td><code>trace_id</code>、<code>span_id</code>、<code>request_id</code></td><td>关联一次请求和 Trace</td></tr><tr><td>事件与业务</td><td><code>event.name</code>、<code>message</code>、<code>order.id</code>、<code>error.type</code></td><td>描述发生了什么</td></tr></tbody></table><p>示例：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-07-30T10:15:32.482Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;severity_text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;INFO&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;订单创建成功&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;event.name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;order.created&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;service.name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;order-service&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;service.version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.3.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;deployment.environment.name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;production&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;trace_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;4bf92f3577b34da6a3ce929d0e0e4736&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;span_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;00f067aa0ba902b7&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;order.id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ord_8f72d1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>字段名应在团队内保持稳定。OpenTelemetry Log Data Model、Semantic Conventions 或 Elastic Common Schema 都可以作为起点；选定一种主规范后再映射到后端，不要让每种语言自行发明字段。</p><h2 id="ri-zhi-ji-bie-yu-shi-jian-xuan-ze" tabindex="-1">日志级别与事件选择 <a class="header-anchor" href="#ri-zhi-ji-bie-yu-shi-jian-xuan-ze" aria-label="Permalink to &quot;日志级别与事件选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>使用建议</th><th>例子</th></tr></thead><tbody><tr><td><code>ERROR</code></td><td>当前操作失败，需要调查或触发告警候选</td><td>数据写入最终失败</td></tr><tr><td><code>WARN</code></td><td>操作已恢复或出现退化，需要关注趋势</td><td>第一次调用超时，重试成功</td></tr><tr><td><code>INFO</code></td><td>低频、关键的业务或生命周期事件</td><td>发布完成、订单状态变更</td></tr><tr><td><code>DEBUG</code></td><td>开发诊断细节，生产环境按需短时开启</td><td>规则分支和中间计算结果</td></tr></tbody></table><p>不要在每一层捕获同一异常后重复打印完整堆栈。通常由最了解业务结果的一层记录一次错误，上层补充状态，下层用 Span 事件或受控的 DEBUG 信息解释细节。</p><p>适合记录的事件包括：</p><ul><li>服务启动、关闭和配置版本变化；</li><li>关键业务状态转换；</li><li>外部依赖失败、重试和熔断状态变化；</li><li>权限、认证和高风险管理操作；</li><li>无法通过指标聚合表达的异常上下文。</li></ul><p>不应直接记录密码、访问令牌、会话标识、连接串、密钥和不必要的个人敏感信息。确有排障需要时，应先做删除、掩码、哈希或加密，并配合最小权限和保留周期。</p><h2 id="dian-xing-ri-zhi-guan-dao" tabindex="-1">典型日志管道 <a class="header-anchor" href="#dian-xing-ri-zhi-guan-dao" aria-label="Permalink to &quot;典型日志管道&quot;">​</a></h2>`,19)),(i(),l(o,null,{default:a(()=>[r(s,{id:"mermaid-224",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E5%BA%94%E7%94%A8%3Cbr%3Estdout%20%2F%20%E6%96%87%E4%BB%B6%20%2F%20OTLP%22%5D%20--%3E%20B%5B%22%E8%8A%82%E7%82%B9%E9%87%87%E9%9B%86%E5%99%A8%3Cbr%3EAlloy%20%2F%20Fluent%20Bit%20%2F%20Vector%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E5%A4%84%E7%90%86%E4%B8%8E%E7%BC%93%E5%86%B2%3Cbr%3E%E8%A7%A3%E6%9E%90%E3%80%81%E8%A1%A5%E5%85%85%E3%80%81%E8%84%B1%E6%95%8F%E3%80%81%E6%89%B9%E5%A4%84%E7%90%86%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E5%8F%AF%E9%80%89%E6%B6%88%E6%81%AF%E7%BC%93%E5%86%B2%3Cbr%3EKafka%20%2F%20Pulsar%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E6%97%A5%E5%BF%97%E5%90%8E%E7%AB%AF%3Cbr%3EElasticsearch%20%2F%20Loki%20%2F%20ClickHouse%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E6%9F%A5%E8%AF%A2%E4%B8%8E%E5%B1%95%E7%A4%BA%3Cbr%3EKibana%20%2F%20Grafana%20%2F%20%E8%87%AA%E5%BB%BA%E5%B9%B3%E5%8F%B0%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<blockquote><p>图示参考：<a href="https://opentelemetry.io/docs/collector/" target="_blank" rel="noreferrer">OpenTelemetry Collector</a> 与 <a href="https://grafana.com/docs/loki/latest/send-data/alloy/" target="_blank" rel="noreferrer">Grafana Loki：Ingesting Logs Using Alloy</a></p></blockquote><p>小规模系统不一定需要独立消息队列，可以由采集器直接写后端。只有在流量突发、跨区域传输、多个下游订阅或后端经常限流时，额外缓冲才可能值得其运维成本。</p><h3 id="ying-yong-shu-chu" tabindex="-1">应用输出 <a class="header-anchor" href="#ying-yong-shu-chu" aria-label="Permalink to &quot;应用输出&quot;">​</a></h3><ul><li>容器应用通常写 <code>stdout</code> / <code>stderr</code>，由平台负责文件落盘、轮转和采集。</li><li>不要让业务线程同步等待远程日志后端，否则可观测系统故障会拖垮业务。</li><li>多行堆栈应在采集阶段正确合并，结构化日志则尽量保持“一行一事件”。</li></ul><h3 id="cai-ji-yu-chu-li" tabindex="-1">采集与处理 <a class="header-anchor" href="#cai-ji-yu-chu-li" aria-label="Permalink to &quot;采集与处理&quot;">​</a></h3><p>采集器负责追踪文件位置、解析格式、补充 Kubernetes 或云资源属性，并在出口失败时批处理和重试。要明确本地缓冲的大小、磁盘上限和溢出策略。</p><p>OpenTelemetry Collector、Grafana Alloy、Fluent Bit 和 Vector 属于采集或处理层，不是日志存储后端。</p><h3 id="chuan-shu-yu-yi" tabindex="-1">传输语义 <a class="header-anchor" href="#chuan-shu-yu-yi" aria-label="Permalink to &quot;传输语义&quot;">​</a></h3><p>日志管道通常只能在成本和可靠性之间取舍：</p><ul><li>进程内异步缓冲延迟低，但进程崩溃时可能丢失未刷新数据。</li><li>磁盘队列更可靠，但要处理容量、损坏和 I/O 竞争。</li><li>至少一次投递可以降低丢失概率，但重试可能产生重复日志。</li><li>端到端“绝不丢失且绝不重复”成本很高，不能因为使用了 Kafka 就默认成立。</li></ul>',10)),(i(),l(o,null,{default:a(()=>[r(s,{id:"mermaid-290",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20A%20as%20%E5%BA%94%E7%94%A8%0A%20%20%20%20participant%20C%20as%20%E9%87%87%E9%9B%86%E5%99%A8%0A%20%20%20%20participant%20Q%20as%20%E6%9C%AC%E5%9C%B0%E7%A3%81%E7%9B%98%E9%98%9F%E5%88%97%0A%20%20%20%20participant%20B%20as%20%E6%97%A5%E5%BF%97%E5%90%8E%E7%AB%AF%0A%20%20%20%20A-%3E%3EC%3A%20%E8%BE%93%E5%87%BA%E6%97%A5%E5%BF%97%E4%BA%8B%E4%BB%B6%20e1%0A%20%20%20%20C-%3E%3EB%3A%20%E6%89%B9%E9%87%8F%E5%8F%91%E9%80%81%20e1%0A%20%20%20%20B--%3E%3EC%3A%20%E8%B6%85%E6%97%B6%E6%88%96%E9%99%90%E6%B5%81%EF%BC%8C%E7%A1%AE%E8%AE%A4%E7%BB%93%E6%9E%9C%E6%9C%AA%E7%9F%A5%0A%20%20%20%20C-%3E%3EQ%3A%20%E6%9A%82%E5%AD%98%20e1%0A%20%20%20%20loop%20%E9%80%80%E9%81%BF%E5%90%8E%E9%87%8D%E8%AF%95%0A%20%20%20%20%20%20%20%20Q-%3E%3EC%3A%20%E8%AF%BB%E5%8F%96%20e1%0A%20%20%20%20%20%20%20%20C-%3E%3EB%3A%20%E5%86%8D%E6%AC%A1%E5%8F%91%E9%80%81%20e1%0A%20%20%20%20end%0A%20%20%20%20B--%3E%3EC%3A%20%E7%A1%AE%E8%AE%A4%E6%8E%A5%E6%94%B6%0A%20%20%20%20Note%20over%20C%2CB%3A%20%E7%AC%AC%E4%B8%80%E6%AC%A1%E5%86%99%E5%85%A5%E4%B9%9F%E5%8F%AF%E8%83%BD%E5%B7%B2%E6%88%90%E5%8A%9F%EF%BC%8C%E5%9B%A0%E6%AD%A4%E5%90%8E%E7%AB%AF%E5%8F%AF%E8%83%BD%E5%87%BA%E7%8E%B0%E9%87%8D%E5%A4%8D%E4%BA%8B%E4%BB%B6%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=t('<blockquote><p>图示参考：<a href="https://opentelemetry.io/docs/collector/resiliency/" target="_blank" rel="noreferrer">OpenTelemetry Collector Resiliency</a> 与 <a href="https://opentelemetry.io/docs/specs/otel/logs/" target="_blank" rel="noreferrer">OpenTelemetry Logging Specification</a></p></blockquote><p>对审计日志等强可靠数据，应把持久化、访问控制、完整性检测和归档作为独立需求，而不是与普通调试日志共用默认策略。</p><h2 id="chang-jian-cun-chu-fang-an-ru-he-xuan-ze" tabindex="-1">常见存储方案如何选择 <a class="header-anchor" href="#chang-jian-cun-chu-fang-an-ru-he-xuan-ze" aria-label="Permalink to &quot;常见存储方案如何选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>数据组织与查询特点</th><th>更适合</th></tr></thead><tbody><tr><td>Elasticsearch / OpenSearch</td><td>倒排索引和全文检索能力强，字段查询灵活</td><td>复杂检索、已有 Elastic 生态</td></tr><tr><td>Loki</td><td>只索引流标签，日志内容在查询时过滤</td><td>已使用 Grafana、标签维度稳定、控制索引成本</td></tr><tr><td>ClickHouse</td><td>列式存储，SQL 聚合与压缩能力强</td><td>大规模结构化日志分析、自建数据平台</td></tr><tr><td>托管日志服务</td><td>与云权限、告警和基础设施集成紧密</td><td>希望减少自建运维、接受平台成本与绑定</td></tr></tbody></table><p>选型前先用真实数据验证：</p><ul><li>每日写入量、峰值吞吐和平均日志大小；</li><li>常用查询是全文关键词、字段过滤还是聚合分析；</li><li>查询时间范围和可接受的响应时间；</li><li>热数据、冷数据的保留周期与恢复要求；</li><li>多租户隔离、访问审计和总成本。</li></ul><h3 id="loki-biao-qian-de-chang-jian-wu-qu" tabindex="-1">Loki 标签的常见误区 <a class="header-anchor" href="#loki-biao-qian-de-chang-jian-wu-qu" aria-label="Permalink to &quot;Loki 标签的常见误区&quot;">​</a></h3><p>Loki 的标签用于定位日志流，应选择值集合有限且长期稳定的字段，例如 <code>service_name</code>、<code>namespace</code>、<code>region</code>。不要把 <code>trace_id</code>、<code>order_id</code>、用户 ID、时间戳或 Pod 唯一标识全部做成标签，否则会产生高基数和大量碎片化日志流。</p><p>高基数字段仍可以保留在日志正文或 structured metadata 中，需要时再过滤。</p><h2 id="traceri-zhi-yu-ye-wu-id-ru-he-guan-lian" tabindex="-1">Trace、日志与业务 ID 如何关联 <a class="header-anchor" href="#traceri-zhi-yu-ye-wu-id-ru-he-guan-lian" aria-label="Permalink to &quot;Trace、日志与业务 ID 如何关联&quot;">​</a></h2><ul><li><code>trace_id</code>：关联同一次分布式请求中的日志和 Span。</li><li><code>span_id</code>：定位日志发生在哪个具体操作内。</li><li><code>request_id</code>：网关或应用自己的请求 ID，可保留用于兼容旧系统。</li><li>业务 ID：如订单号，适合查询跨越多个异步流程的业务生命周期。</li></ul><p>同步调用通常传播当前 Trace Context；消息队列还要把上下文写入消息属性。消费端如果启动新的 Trace，可以通过 Span Link 保留与生产端的因果关系。业务 ID 不应替代 Trace ID，因为一次业务流程可能包含多条 Trace，一条 Trace 也可能访问多个业务实体。</p>',12)),(i(),l(o,null,{default:a(()=>[r(s,{id:"mermaid-430",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20M%5B%22%E6%8C%87%E6%A0%87%E5%BC%82%E5%B8%B8%3Cbr%3Eservice%20%2F%20region%20%2F%20version%22%5D%20--%3E%7CExemplar%7C%20T%5B%22Trace%3Cbr%3Etrace_id%22%5D%0A%20%20%20%20T%20--%3E%7Cspan_id%7C%20L%5B%22%E5%85%B7%E4%BD%93%20Span%20%E5%86%85%E7%9A%84%E6%97%A5%E5%BF%97%22%5D%0A%20%20%20%20L%20--%3E%7Corder.id%7C%20B%5B%22%E8%B7%A8%20Trace%20%E7%9A%84%E4%B8%9A%E5%8A%A1%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20%20%20D%5B%22%E9%83%A8%E7%BD%B2%E4%B8%8E%E9%85%8D%E7%BD%AE%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%7Cversion%20%2F%20time%7C%20M%0A%20%20%20%20D%20--%3E%7Cservice.version%7C%20T%0A"})]),fallback:a(()=>[...e[2]||(e[2]=[n(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=t('<blockquote><p>图示参考：<a href="https://opentelemetry.io/docs/specs/otel/logs/#log-correlation" target="_blank" rel="noreferrer">OpenTelemetry Logging：Log Correlation</a></p></blockquote><h2 id="gu-zhang-pai-cha-de-cha-xun-shun-xu" tabindex="-1">故障排查的查询顺序 <a class="header-anchor" href="#gu-zhang-pai-cha-de-cha-xun-shun-xu" aria-label="Permalink to &quot;故障排查的查询顺序&quot;">​</a></h2><p>面对一次线上错误，可以按以下顺序收敛：</p><ol><li>用时间范围、环境、服务和版本找到候选日志。</li><li>从一条错误日志取得 <code>trace_id</code>，查看完整调用路径。</li><li>回到慢 Span 对应的日志，检查业务参数、重试和异常类型。</li><li>用业务 ID 查找异步后续事件，确认最终状态。</li><li>对照发布和配置变更事件，验证问题是否与版本相关。</li></ol><p>如果只能全文搜索错误字符串，说明日志数据模型仍然不足；如果能找到错误却关联不到 Trace，优先检查上下文注入和异步传播。</p><h2 id="shang-xian-jian-cha-qing-dan" tabindex="-1">上线检查清单 <a class="header-anchor" href="#shang-xian-jian-cha-qing-dan" aria-label="Permalink to &quot;上线检查清单&quot;">​</a></h2><ul><li>[ ] 日志采用稳定的结构化格式，所有服务统一时间和级别字段。</li><li>[ ] 服务名、版本、环境、区域等资源属性可过滤。</li><li>[ ] Trace 激活时自动注入 <code>trace_id</code> 和 <code>span_id</code>。</li><li>[ ] 已定义敏感字段清单，并在应用或采集器侧过滤。</li><li>[ ] 文件轮转、内存/磁盘队列、重试和溢出策略有明确上限。</li><li>[ ] 采集器拒收、丢弃、导出失败和队列饱和有独立监控。</li><li>[ ] 保留周期、访问权限和删除流程符合业务与合规要求。</li><li>[ ] 用后端不可用、磁盘写满和重复投递场景做过演练。</li></ul><h2 id="xue-xi-zi-ce" tabindex="-1">学习自测 <a class="header-anchor" href="#xue-xi-zi-ce" aria-label="Permalink to &quot;学习自测&quot;">​</a></h2><ol><li>为什么写入 <code>stdout</code> 不等于日志已经可靠进入中央存储？</li><li>至少一次投递对日志查询会带来什么副作用？</li><li>为什么 <code>trace_id</code> 适合保存在日志字段中，却不适合做 Loki 流标签？</li><li>审计日志与普通 DEBUG 日志为什么不应使用完全相同的策略？</li></ol><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>OpenTelemetry Specification：<a href="https://opentelemetry.io/docs/specs/otel/logs/" target="_blank" rel="noreferrer">Logs</a></li><li>OpenTelemetry：<a href="https://opentelemetry.io/docs/collector/resiliency/" target="_blank" rel="noreferrer">Collector Resiliency</a></li><li>OpenTelemetry：<a href="https://opentelemetry.io/docs/specs/semconv/resource/service/" target="_blank" rel="noreferrer">Service Semantic Conventions</a></li><li>Elastic：<a href="https://www.elastic.co/guide/en/ecs-logging/overview/current/intro.html" target="_blank" rel="noreferrer">ECS Logging</a></li><li>Grafana Loki：<a href="https://grafana.com/docs/loki/latest/get-started/labels/" target="_blank" rel="noreferrer">Understand Labels</a></li><li>Grafana Loki：<a href="https://grafana.com/docs/loki/latest/send-data/alloy/" target="_blank" rel="noreferrer">Ingesting Logs Using Alloy</a></li><li>OWASP Cheat Sheet Series：<a href="https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html" target="_blank" rel="noreferrer">Logging Cheat Sheet</a></li></ul>',11))])}const y=d(c,[["render",p]]);export{m as __pageData,y as default};
